package configuration

import (
	"slices"
	"strings"

	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/engine"
	"github.com/anthnel/devdesk/internal/scan"

	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View renders the active tab's fields. The tab bar itself lives in the footer
// so it stays visible when the list scrolls (Rule 123).
//
// A tab taller than the viewport scrolls: the scan tab alone ran past seventy
// lines, and with nothing scrolling the bottom of it was simply cut off.
func (m Model) View() string {
			return theme.KeyStyle.Render(prefix) + theme.Bg(value)
		}
		return theme.Bg(prefix) + theme.DimStyle.Render(value)
	}

	if focused {
		if f.Kind == kindCycle {
			return theme.KeyStyle.Render(prefix) + theme.Bg(f.Value(m.config))
		}
		return theme.KeyStyle.Render(prefix) + m.input.View()
	}
	value := f.Value(m.config)
	if f.path {
		// Shortened only at rest: the input shows it whole while it is edited.
		value = theme.ShortPath(value, width-lipgloss.Width(prefix))
	}
// fieldHead is everything before the chevron: the label, plus the select icon a
// closed-list field carries (Rule 132's ordering).
func fieldHead(f field) string {
	switch {
	case f.Kind == kindCycle:
		return f.Label + " " + theme.IconSelect
	case f.path:
		// The browse marker (§3.95): enter opens the file browser, the way
		// the select icon says ←→ cycles.
		return f.Label + " " + theme.IconBrowse
	}
// hint is what the footer says about a field while it has the focus. A
// checkbox says what it does in the state it is in — and why it cannot move,
// when it cannot — so the effect of space is read as it is pressed (§3.86).
// It is a state, not an event: it goes through Status, with no timer.
func (m Model) hint(f field) string {
	if reason := m.lockReason(f); reason != "" {
		return reason
	}
	if f.Kind == kindToggle && (f.hintOn != "" || f.hintOff != "") {
		if f.Bool(m.config) {
			return f.hintOn
		}
		return f.hintOff
	}
	if f.path {
		if f.hint == "" {
			return "enter opens the file browser"
		}
		), true
	}
	return m, m.persist(saved{}), true
}

// cycleField advances a closed-set field (Rule 132).
func (m Model) cycleField(step int) (tea.Model, tea.Cmd) {
	f := m.current()
	if f.Kind != kindCycle {
		return m, nil
	}
	f.Cycle(m.config, step)

	// The theme is the one setting whose effect is the screen itself, so it is
	// applied as it is cycled rather than on blur — otherwise the user is
	// choosing blind.
	if f.Label == themeLabel {
		return m, m.persist(saved{theme: true})
	}
	// The backend is confirmed on blur, so nothing is written here.
	if f.Label == secretBackendLabel {
		return m, nil
	}
	// The engine is settled on blur, same reasoning: cycling auto → docker →
	// podman would otherwise re-resolve three times, including on the way back
	// to where it started.
44:// Level is a footer message's severity. It decides the colour and nothing else.
48://	LevelError   — an operation failed, or the system refused it.
49://	LevelWarning — the action cannot be honoured as asked, but nothing failed:
51://	LevelInfo    — a neutral fact, or an operation that succeeded.
52:type Level int
55:	LevelInfo Level = iota
56:	LevelWarning
57:	LevelError
61:func (l Level) Style() lipgloss.Style {
63:	case LevelError:
46:		{"Theme", "←→", []string{"space"}},

